sysevent_in_email_action.script:
(function runAction(/*GlideRecord*/ current, /*GlideRecord*/ event, /*EmailWrapper*/ email, /*ScopedEmailLogger*/ logger, /*EmailClassifier*/ classifier) {

	var asset = email.body.asset_type;

	var groupName = '';
	var assetType = '';

	if (asset == 'Computer') {
        groupName = 'Computers';
		assetType = 'computer';
    } else if (asset == 'Network Gear') {
        groupName = 'Network Gear';
		assetType = 'netgear';
    } else if (asset == 'Printer') {
        groupName = 'Printers';
		assetType = 'printer';
    } else if (asset == 'UPS') {
        groupName = 'UPS';
		assetType = 'ups';
    }

	current.type_of_asset = assetType;
    current.consumables = email.body.consumables.toLowerCase();
    current.priority = email.body.priority;

	// assign priority to critical when the user is vip
	var grUser = new GlideRecord('sys_user');

	if (grUser.get(gs.getUserID())) {
		if (grUser.getValue('vip') == '1') {
			current.priority = '1';
		}
	}

	// get group name based on asset

	var grGroup = new GlideRecord('sys_user_group');
	if (grGroup.get('name', groupName)) {
		current.assignment_group = grGroup.getUniqueValue();
	}

})(current, event, email, logger, classifier);
